CREATE TABLE sites (
	name VARCHAR(200) NOT NULL, 
	gps_lat FLOAT, 
	gps_lng FLOAT, 
	address TEXT, 
	landmarks TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	version INTEGER DEFAULT 1 NOT NULL, 
	source VARCHAR(24) DEFAULT 'manual' NOT NULL, 
	extra JSONB DEFAULT '{}' NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (gps_lat BETWEEN -90 AND 90), 
	CHECK (gps_lng BETWEEN -180 AND 180), 
	CHECK ((gps_lat IS NULL) = (gps_lng IS NULL)), 
	CONSTRAINT ck_sites_version CHECK (version >= 1)
);

